def is_regular_sequence(s, k):
    n = len(s)
    if n < 2 * k + 1:
        return False

    for i in range(1, n // 2 + 1):
        if n % (2 * i) != 2 * k + 1:
            continue

        A = s[:i]
        B = s[i:i + i]

        j = i + i
        while j < n:
            if s[j:j + i] != A or s[j + i:j + 2 * i] != B:
